const $=s=>document.querySelector(s), money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const media=window.originalMedia||{};
const productImage=p=>p.image||media.products?.[p.id]||`/assets/${p.art}.svg`;
function originalVideo(id,poster,webm,mp4){return `<video id="${id}" class="original-video" muted loop playsinline preload="none" poster="${poster}" aria-hidden="true">${webm?`<source src="${webm}" type="video/webm">`:''}${mp4?`<source src="${mp4}" type="video/mp4">`:''}</video>`}
const games=[{id:'bloxfruits',name:'Blox Fruits',art:'adventure',desc:'Contas, frutas e gamepasses para evoluir mais rápido.'},{id:'brainrot',name:'Steal a Brainrot',art:'creatures',desc:'Itens e opções para jogar com mais vantagem.'},{id:'mm2',name:'MM2',art:'mystery',desc:'Itens e gamepasses para jogar com mais estilo.'}];
const products=[['Dark Blade',47.45,'bloxfruits','Gamepasses','sword'],['Notificador de Frutas',105.85,'bloxfruits','Gamepasses','gem'],['2x Dinheiro',20.08,'bloxfruits','Gamepasses','coin'],['2x Maestria',20.08,'bloxfruits','Gamepasses','gem'],['+1 Espaço no Baú',18.25,'bloxfruits','Gamepasses','coin'],['Barcos Rápidos',16.43,'bloxfruits','Gamepasses','sword'],['Divine Portal Skin',144.9,'bloxfruits','Skins de fruta','gem'],['Torment Pain',19.9,'bloxfruits','Skins de fruta','gem'],['Dragon',200.75,'bloxfruits','Frutas Permanentes','fruit'],['Kitsune',164.25,'bloxfruits','Frutas Permanentes','fruit'],['Buddha',60.23,'bloxfruits','Frutas Permanentes','fruit'],['Magma',47.45,'bloxfruits','Frutas Permanentes','fruit'],['Gelo',27.38,'bloxfruits','Frutas Permanentes','fruit'],['Portal',80.30,'bloxfruits','Frutas Permanentes','gem'],['VIP',29.9,'brainrot','Gamepasses','coin'],['2x Dinheiro',19.9,'brainrot','Gamepasses','coin'],['Base Dourada',49.9,'brainrot','Skins de Base','gem'],['Base Galáctica',79.9,'brainrot','Skins de Base','gem'],['Chroma Luger',59.9,'mm2','Armas','sword'],['Saw',19.9,'mm2','Facas','sword'],['Hallowscythe',49.9,'mm2','Facas','sword'],['Waves',39.9,'mm2','Facas','sword'],['Set Galáxia',89.9,'mm2','Sets','gem'],['Elite',24.9,'mm2','Gamepasses','coin'],['Conta Blox Fruits — Level 2800',4.99,'accounts','Contas','adventure']].map((p,id)=>({id,name:p[0],price:p[1],game:p[2],category:p[3],art:p[4]}));
window.catalogData?.accounts.forEach(p=>{p.id=products.length;products.push({...p,game:'accounts',category:'Contas Blox Fruits',art:'adventure'})});
window.catalogData?.gifts.forEach(p=>{p.id=products.length;products.push({...p,name:'Gift Card Roblox · R$ '+p.value,game:'giftcards',category:'Gift Card Roblox',art:'coin'})});
// Keep existing product identifiers stable for saved carts.
products[22].archived=true;products[23].archived=true;
window.mm2Products?.forEach(item=>{let p=products.find(p=>p.game==='mm2'&&!p.archived&&p.name===item.name);if(p)Object.assign(p,item);else products.push({...item,id:products.length,game:'mm2',art:item.category==='Sets'?'gem':'sword'})});
const bloxKey=name=>name.toLowerCase().replace(/[()]/g,'').replace(/\bskin\b/g,'').replace(/\s+/g,' ').trim();
window.bloxProducts?.forEach(item=>{const p=products.find(p=>p.game==='bloxfruits'&&bloxKey(p.name)===bloxKey(item.name));if(p)Object.assign(p,item);else products.push({...item,id:products.length,game:'bloxfruits',art:item.category==='Frutas Permanentes'?'fruit':'gem'})});
products[16].archived=true;products[17].archived=true;
window.brainrotProducts?.forEach(item=>{const p=products.find(p=>p.game==='brainrot'&&!p.archived&&p.name.toLowerCase()===item.name.toLowerCase());if(p)Object.assign(p,item);else products.push({...item,id:products.length,game:'brainrot',art:'coin'})});
products.forEach(p=>{p.price=window.shopPricing.discount(p.price)});
window.catalogData?.accounts.forEach(p=>{p.price=products[p.id].price});
window.catalogData?.gifts.forEach(p=>{p.price=products[p.id].price});
products[24].archived=true;
window.productPages?.configure(products);
const faqs=[['O que posso comprar na loja?','Explore Robux, gamepasses, itens e contas pelas categorias. Confira os detalhes e o valor do seu pedido antes de continuar.'],['Como escolho o jogo ou produto certo?','Selecione um jogo, use a busca e filtre pela categoria. Abra o produto para conferir os detalhes.'],['Preciso passar minha senha Roblox?','Não. Informe somente o nome de usuário Roblox e seu e-mail. A consulta do perfil usa apenas informações públicas.'],['Qual é a diferença entre Robux e produtos de jogo?','Robux é a moeda virtual da plataforma. Os produtos de jogo são itens ou vantagens de uma experiência específica.'],['Como funciona a entrega?','O método depende do produto. O pagamento pode ser realizado por PIX quando habilitado. A entrega não é automática nesta versão e deve ser acompanhada pelo responsável da loja.'],['Como acompanho meu pedido?','Abra Minha conta e depois Meus pedidos. Os pedidos ficam neste navegador e os pagamentos PIX são consultados na PurinCash.'],['E se eu escolher o produto errado?','Você pode alterar quantidades ou remover qualquer produto do carrinho antes de gerar o pagamento.']];
const guide=[['O que é a loja?','Uma base visual que organiza produtos digitais por jogo, com busca, categorias e informações antes da compra.'],['O que posso comprar?','O catálogo reúne Robux, gamepasses, frutas, skins, itens e contas. Confira disponibilidade, valor e conteúdo descritos na página do produto.'],['Como escolher entre Robux e produtos de jogo?','Escolha Robux para explorar a moeda da plataforma. Para um item específico, entre na página do jogo e consulte sua categoria.'],['Como funcionam as páginas de jogo?','Cada jogo tem uma busca própria e filtros por tipo de produto. Abra os detalhes ou adicione um item ao carrinho para experimentar o fluxo.'],['Como funciona a entrega?','Confira o método na página do produto e acompanhe o status em Meus pedidos. A integração de pagamento não realiza a entrega automática dos itens.'],['Preciso passar minha senha?','Nunca informe senha, token ou cookie Roblox. A busca usa o perfil público; o e-mail de contato é utilizado no pedido e na cobrança.'],['O que conferir antes de comprar?','Confira nome, jogo, quantidade e valor. Em uma loja real, também é necessário confirmar disponibilidade, regras e método de entrega.']];
function validRobuxRow(row){return row&&row.kind==='robux'&&Number.isInteger(row.robuxQuantity)&&row.robuxQuantity>=window.shopPricing.minimumRobuxQuantity&&row.robuxQuantity<=22500&&['gamepass','plus','giftcard'].includes(row.method)&&row.id==='robux-'+row.robuxQuantity+'-'+row.method}
function getCartItem(row){return validRobuxRow(row)?{id:row.id,name:row.robuxQuantity.toLocaleString('pt-BR')+' Robux · '+(row.method==='plus'?'Roblox Plus':row.method==='giftcard'?'Gift Card personalizado':'Via Gamepass'),price:window.shopPricing.robux(row.robuxQuantity)}:products[row.id]}
let cart;try{cart=JSON.parse(localStorage.getItem('demo-cart')||'[]');if(!Array.isArray(cart))cart=[];cart=cart.filter(x=>x&&(validRobuxRow(x)||(Number.isInteger(x.id)&&products[x.id]&&!products[x.id].archived))&&Number.isInteger(x.qty)&&x.qty>0).map(x=>({...x,qty:Math.min(x.qty,Number.isInteger(x.id)&&products[x.id]?.game==='accounts'?Math.min(99,products[x.id].stock||1):99)}))}catch{cart=[]}
games.forEach(g=>g.image=({bloxfruits:media.bloxThumb,brainrot:media.brainThumb,mm2:media.mmThumb,custom:media.collage})[g.id]||`/assets/${g.art}.svg`);
let shopMethod='plus';
let qty=1000, filter='Todos',query='',gameQuery='';
function save(){localStorage.setItem('demo-cart',JSON.stringify(cart));$('#count').textContent=cart.reduce((s,x)=>s+x.qty,0)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function openModal(html,kind='product'){const replacing=$('#modal').open;$('#modal-body').innerHTML=html;if(!replacing)$('#modal').showModal();window.lojaMotion?.showDialog(kind,replacing);}
function closeModal(immediate=false){if(window.lojaMotion)window.lojaMotion.closeDialog(immediate);else $('#modal').close();}
const maxCartQuantity=id=>Number.isInteger(id)&&products[id]?.game==='accounts'?Math.min(99,products[id].stock||1):99;
function add(id){return window.lojaCart.addProduct({id,qty:1})}
function cartModal(){const total=cart.reduce((sum,row)=>sum+getCartItem(row).price*row.qty,0);openModal(`<h2>Seu carrinho</h2>${cart.length?cart.map(row=>{const p=getCartItem(row);return `<div class="cart-row"><div><b>${p.name}</b><small>${money(p.price)}</small></div><button data-step="${p.id},-1" aria-label="Diminuir ${p.name}">−</button><span>${row.qty}</span><button data-step="${p.id},1" aria-label="Aumentar ${p.name}">+</button><button class="remove" data-remove="${p.id}" aria-label="Remover ${p.name}">×</button></div>`}).join(''):`<div class="empty">Seu carrinho está vazio.<br>Explore os jogos e encontre um produto.</div>`}<div class="total"><p>Total</p><strong>${money(total)}</strong></div><div class="demo">${window.paymentUI?.enabled?'Confira os itens antes de gerar seu PIX.':'Demonstração local · nenhum pagamento será cobrado.'}</div>${cart.length?'<button class="button" data-checkout>Finalizar compra →</button>':'<button class="button" data-close>Continuar comprando</button>'}`,'cart')}
function startCheckout(){const purchased=cart.map(row=>({...row}));window.checkoutFlow?.open(purchased.map(row=>{const p=getCartItem(row);return {id:row.id,name:p.name,price:p.price,qty:row.qty}}),()=>{for(const row of purchased){const live=cart.find(x=>x.id===row.id);if(live)live.qty-=row.qty}cart=cart.filter(row=>row.qty>0);save()})}
function productModal(id){const p=products[id];if(!p||p.archived)return;history.pushState({},'',window.productPages.url(p));render();window.scrollTo(0,0)}
function calculator(){return `<div class="calculator"><h3>◇ Comprar Robux</h3><p style="font-size:12px">Escolha a quantidade e o método</p><div class="methods"><button class="method" data-shop-method="giftcard" aria-pressed="${shopMethod==='giftcard'}">VIA GIFT CARD<small>Criar com o valor selecionado</small></button><button class="method" data-shop-method="plus" aria-pressed="${shopMethod==='plus'}">ROBLOX PLUS<small>R$ 25,55 / 1k</small></button></div>${shopMethod==='giftcard'?'<div class="notice">Escolha um Gift Card e confira o saldo disponível para resgatar na sua conta Roblox.</div><a class="button" style="width:100%;margin-top:24px" href="/gift-cards">Escolher Gift Card →</a>':`<div class="notice">Selecione a quantidade e continue via Roblox Plus. Valor mínimo: R$ 15,00.</div><label for="quantity">QUANTIDADE</label><input class="quantity" id="quantity" type="number" min="${window.shopPricing.minimumRobuxQuantity}" max="22500" step="1" value="${qty}"><div class="presets">${[window.shopPricing.minimumRobuxQuantity,1000,2000,5000].map(n=>`<button data-qty="${n}" class="${n===qty?'selected':''}">${n>=1000?n/1000+'K':n}</button>`).join('')}</div><div class="total"><small>VOCÊ PAGA</small><strong id="robux-price">${money(window.shopPricing.robux(qty))}</strong></div><div class="economized" id="economized">Economize ${money(qty*.06-window.shopPricing.robux(qty))} · No Roblox: ${money(qty*.06)}</div><button class="button" data-robux>Continuar via Roblox Plus →</button>`}</div>`}

function home(){return `<section class="hero">${originalVideo('hero-video',media.heroPoster,media.heroVideo)}<div class="wrap reveal"><div class="breadcrumb"><a href="/">Início</a><span>›</span>Loja</div><h1>A Sua Loja de <em>Roblox</em></h1><p>Escolha Robux, contas, gamepasses e itens com entrega de 24h a 48h úteis pela StarBuxx.</p><label class="search">⌕<input id="game-search" placeholder="Buscar na loja" aria-label="Buscar na loja"></label></div></section><section id="escolha-jogo"><div class="wrap"><h2>Escolha seu <em>jogo</em></h2><p>Clique no jogo que você quer comprar e veja as opções disponíveis.</p><div class="rule"></div><div class="games">${games.map(g=>`<a class="game" data-game-name="${g.name.toLowerCase()}" href="${g.id==='custom'?'/gamepass':'/loja/'+g.id}" style="--art:url('${g.image}')"><h3>${g.name}</h3><p>${g.desc}</p><span class="choose">ESCOLHER JOGO <span>›</span></span></a>`).join('')}</div><div class="empty hide" id="game-empty">Nenhum jogo encontrado.</div></div></section><section id="contas"><div class="wrap"><h2>Contas <em>prontas</em> para jogar</h2><p>Escolha uma conta e veja os detalhes antes de comprar.</p><div class="account-main"><div class="account-art">${originalVideo('account-video',media.bloxPoster,media.bloxVideo,media.bloxMp4)}<span class="verified">✓ CONTAS VERIFICADAS</span></div><div class="account-copy"><img class="blox-wordmark" src="${media.bloxLogo}" alt="Blox Fruits"><h3>Contas completas prontas para o PVP</h3><div class="chips">${['Level 2800','Raça V4 Human','Frutas Míticas','Dragon','CDK Max'].map((t,i)=>`<span class="chip">${i?`<img src="${[null,media.human,media.products[9],media.products[8],media.cdk][i]}" alt="">`:''}${t}</span>`).join('')}</div><div class="account-bottom"><div><span class="eyebrow">A PARTIR DE</span><div class="price"><small>R$</small> ${Math.min(...window.catalogData.accounts.map(p=>p.price)).toLocaleString('pt-BR',{minimumFractionDigits:2})}</div></div><a class="button" href="/contas">VER CONTA →</a></div></div></div><div class="stock"><img src="${media.brainThumb}" alt="Steal a Brainrot"><div><h3>Steal a Brainrot</h3><small>AGUARDANDO ESTOQUE · EM BREVE</small></div></div></div></section><section id="robux-pacotes"><div class="wrap"><h2>Compre Robux com <em>economia</em> real</h2><p>Veja quanto você recebe e compare antes de finalizar.</p><div class="economy"><div class="saving"><div class="economy-visual" aria-hidden="true"><div class="economy-bars"><i style="--bar:90%;--delay:-0s"></i><i style="--bar:82%;--delay:-0.4s"></i><i style="--bar:78%;--delay:-0.8s"></i><i style="--bar:72%;--delay:-1.2000000000000002s"></i><i style="--bar:66%;--delay:-1.6s"></i><i style="--bar:58%;--delay:-2s"></i><i style="--bar:50%;--delay:-2.4000000000000004s"></i><i style="--bar:42%;--delay:-2.8000000000000003s"></i></div><svg class="economy-line" viewBox="0 0 420 190" preserveAspectRatio="none"><path d="M4 10C60 35 70 28 112 60S180 87 210 112 290 140 325 158 370 174 416 187"/></svg><img class="economy-float" src="${media.robux}" alt="" style="--delay:-0s"><img class="economy-float" src="${media.roblox}" alt="" style="--delay:-0.9s"><img class="economy-float" src="${media.robux}" alt="" style="--delay:-1.8s"><img class="economy-float" src="${media.roblox}" alt="" style="--delay:-2.7s"><img class="economy-float" src="${media.robux}" alt="" style="--delay:-3.6s"><span class="economy-discount discount-1" style="--delay:0s">−18%</span><span class="economy-discount discount-2" style="--delay:-2s">−26%</span><span class="economy-discount discount-3" style="--delay:-4s">−42%</span><div class="economy-emblem"><div class="orbit-ring"></div><img class="economy-brand-image" src="${media.logo}" alt=""></div></div><div class="saving-copy"><span class="eyebrow">◇ ECONOMIA REAL</span><h2>ATÉ <em>42%</em><br>mais barato que no Roblox</h2><p>Robux mais baratos através da compra de moedas em jogos populares do Roblox, com entrega de 24h a 48h úteis e suporte humano.</p><div class="trust"><span>♢ 100% SEGURO</span><span>✓ ENTREGA ACOMPANHADA</span><span>◉ SUPORTE HUMANO</span></div></div></div>${calculator()}</div></div></section><section id="faq"><div class="wrap faq"><h2>Tudo sobre a <em>Loja StarBuxx</em></h2><p>Robux, jogos, contas e entregas — respostas rápidas antes de comprar.</p><div class="rule"></div>${faqs.map(([q,a])=>`<details><summary>${q}</summary><div class="faq-answer"><p>${a}</p></div></details>`).join('')}</div></section><section><div class="wrap"><span class="eyebrow">GUIA DA LOJA</span><h2 class="guide-heading" style="font-size:36px;margin-top:12px">Guia rápido sobre a Loja StarBuxx</h2><p>Entenda como escolher Robux, jogos, contas, gamepasses e itens antes de comprar.</p><div class="guide"><aside>${guide.map(([q],i)=>`<a href="#guia-${i}">${q}</a>`).join('')}</aside><div>${guide.map(([q,a],i)=>`<article id="guia-${i}"><h3>${q}</h3><p>${a}</p></article>`).join('')}<a class="button" href="#escolha-jogo">VER PRODUTOS ↑</a></div></div></div></section><section class="cta"><div class="wrap"><h2>Existe loja <em>barata.</em><br>Existe loja <em>segura.</em><br>A StarBuxx é as duas.</h2><p>Robux e Gamepasses com entrega acompanhada e suporte humano. Explore a experiência nesta demonstração.</p><a class="button" href="/robux">Comprar Robux →</a><div class="cta-orbits" aria-hidden="true"><span style="--delay:-0s;--glow:#22d3ee88"><img src="/assets/original/4fbb2388bf769040.png" alt=""></span><span style="--delay:-0.8s;--glow:#fbbf2488"><img src="/assets/original/9e4a9a1bfc31d718.png" alt=""></span><span style="--delay:-1.6s;--glow:#4ade8088"><img src="/assets/original/5f7d32c7be69b510.png" alt=""></span><span style="--delay:-2.4000000000000004s;--glow:#a855f788"><img src="/assets/original/1e7e0251d8e59da3.png" alt=""></span><span style="--delay:-3.2s;--glow:#f9731688"><img src="/assets/original/570507b5e2ef9723.svg" alt=""></span></div><button class="backtop" data-top>↑ Voltar ao topo da loja</button></div></section>`}
function productCard(p){return `<article class="product"><button class="product-art" style="width:100%;cursor:pointer;color:inherit" data-product="${p.id}" aria-label="Ver detalhes de ${p.name}"><span class="badge">${p.game==='mm2'?(p.category==='Sets'?'SET':'TRADE'):p.category==='Frutas Permanentes'?'PERMANENTE':p.category.includes('Skin')?'TRADE':'PRESENTE'}</span><img loading="lazy" src="${productImage(p)}" data-fallback="/assets/${p.art}.svg" alt="${p.name}"></button><h4>${p.name}</h4><div class="product-price">${money(p.price)}</div><div class="product-actions"><button class="icon" data-add="${p.id}" aria-label="Adicionar ${p.name} ao carrinho">+</button><button class="button" data-product="${p.id}">COMPRAR AGORA</button></div></article>`}
function catalog(id){const g=games.find(g=>g.id===id);const cats=[...new Set(products.filter(p=>p.game===id&&!p.archived).map(p=>p.category))];return `<section class="catalog-hero-video catalog-hero"><div class="catalog-hero-copy"><div class="breadcrumb"><a href="/">Início</a> › <a href="/loja">Loja</a> › ${g.name}</div><h1><em>${g.name}</em><br>${id==='bloxfruits'?'gamepasses, frutas e skins':id==='mm2'?'facas, armas e sets':'gamepasses e skins de base'}</h1><p>Encontre produtos de ${g.name} com entrega acompanhada e suporte humano — sem precisar passar sua senha Roblox.</p><a class="button" href="#catalog-products">Ver produtos ↓</a></div><div class="catalog-media ${id}">${id==='bloxfruits'?originalVideo('catalog-video',media.bloxPoster,media.bloxVideo,media.bloxMp4):`<img src="${id==='brainrot'?media.brainHero:media.mmHero}" alt="${g.name}">`}<img class="catalog-game-logo" src="${id==='bloxfruits'?media.bloxLogo:g.image}" alt="${g.name}"></div></section><div class="live"><div class="live-heading"><span>● DEMONSTRAÇÃO</span>Movimento da Comunidade</div><div class="ticker-viewport" tabindex="0" aria-label="Categorias da loja em movimento"><div class="ticker-track"><div class="ticker-group"><div class="ticker-item"><img class="ticker-robux-icon" src="/assets/original/570507b5e2ef9723.svg" alt=""><b>Robux</b><small>Roblox Plus</small></div><div class="ticker-item">✦<b>Blox Fruits</b><small>Frutas e gamepasses</small></div><div class="ticker-item">♢<b>MM2</b><small>Facas, armas e sets</small></div><div class="ticker-item">⬡<b>Steal a Brainrot</b><small>Skins de Base</small></div><div class="ticker-item">✓<b>Carrinho local</b><small>Explore a demonstração</small></div></div><div class="ticker-group" aria-hidden="true"><div class="ticker-item"><img class="ticker-robux-icon" src="/assets/original/570507b5e2ef9723.svg" alt=""><b>Robux</b><small>Roblox Plus</small></div><div class="ticker-item">✦<b>Blox Fruits</b><small>Frutas e gamepasses</small></div><div class="ticker-item">♢<b>MM2</b><small>Facas, armas e sets</small></div><div class="ticker-item">⬡<b>Steal a Brainrot</b><small>Skins de Base</small></div><div class="ticker-item">✓<b>Carrinho local</b><small>Explore a demonstração</small></div></div></div></div></div><div class="wrap" id="catalog-products"><div class="filters"><select id="category" aria-label="Filtrar produtos"><option>Todos</option>${cats.map(c=>`<option>${c}</option>`).join('')}</select><label class="search">⌕<input id="product-search" type="search" aria-label="Buscar produtos de ${g.name}" placeholder="Buscar produtos de ${g.name}..."></label></div><div id="catalog-list">${catalogList(id)}</div>${id==='brainrot'?'<section class="catalog-section"><h2>Skins de Base</h2><div class="empty">Nenhuma skin de base disponível no momento.</div></section>':''}</div>`}
function catalogList(id){const list=products.filter(p=>p.game===id&&!p.archived&&(filter==='Todos'||p.category===filter)&&p.name.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>['mm2','bloxfruits','brainrot'].includes(id)?a.order-b.order:0);if(!list.length)return '<div class="empty">Nenhum produto encontrado. Experimente outra busca ou categoria.</div>';return [...new Set(list.map(p=>p.category))].map(c=>`<section class="catalog-section"><h2>${c} <em>${games.find(g=>g.id===id).name}</em></h2><p>Produtos ilustrativos · consulte os detalhes antes de simular.</p><div class="product-grid">${list.filter(p=>p.category===c).map(productCard).join('')}</div></section>`).join('')}
function generic(path){const accountSection=window.accountUI?.sectionPage(path);if(accountSection)return accountSection;if((path==='/perfil'||path==='/minha-conta')&&window.accountUI)return window.accountUI.page();if(path==='/meus-pedidos'&&window.ordersPage)return window.ordersPage.page();if(path==='/gift-cards'&&window.specialCatalog)return window.specialCatalog.gifts();if((path==='/contas'||path==='/contas/jogo/blox-fruits')&&window.specialCatalog)return window.specialCatalog.accounts();if(path==='/robux'&&window.robuxPage)return window.robuxPage.page(products);if(path==='/robux')return `<section class="page wrap"><div class="breadcrumb"><a href="/loja">Loja</a> › Robux</div><h1>Comprar <em>Robux</em></h1><p>Escolha sua quantidade e simule o valor.</p><div style="max-width:520px;margin:35px auto">${calculator()}</div></section>`;if(path.startsWith('/contas'))return `<section class="page wrap"><h1>Contas <em>prontas para jogar</em></h1><p>Catálogo demonstrativo · consulte os detalhes.</p><div class="product-grid">${productCard(products.at(-1))}</div></section>`;if(path==='/auth'&&window.robloxAccount)return window.robloxAccount.page();if(path==='/auth')return `<section class="page wrap"><div class="info-box"><span class="eyebrow">SUA CONTA</span><h1 style="margin:16px 0">Bem-vindo de volta</h1><p>Acesse sua conta para acompanhar seus pedidos.</p><form id="login"><label>E-mail<input type="email" placeholder="seu@email.com" required></label><div class="demo">Interface demonstrativa. Não informe senhas reais. Nenhum dado será enviado.</div><button class="button" style="width:100%;margin-top:20px">Simular acesso</button></form></div></section>`;if(path==='/gamepass')return `<section class="page wrap"><h1>Qualquer <em>jogo</em></h1><div class="info-box"><h3>Gamepass personalizada</h3><p>Informe o jogo e a quantidade para montar uma simulação.</p><form id="custom"><label>Nome do jogo<input required placeholder="Qual jogo você quer jogar?"></label><label>Quantidade de Robux<input required type="number" min="100" max="100000" value="1000"></label><button class="button">Simular gamepass</button></form><div class="demo">Solicitação local, sem envio de dados ou compra real.</div></div></section>`;const titles={'/suporte':'Central de ajuda','/sobre-nos':'Sobre esta recriação','/termos':'Termos de uso','/privacidade':'Privacidade','/reembolso':'Vendas e reembolso','/gift-cards':'Gift Cards','/scripts':'Scripts'};return `<section class="page wrap"><h1>${titles[path]||'Página não encontrada'}</h1><div class="info-box"><h3>${path==='/gift-cards'||path==='/scripts'?'Em breve':'Projeto independente de demonstração'}</h3><p>${path==='/privacidade'?'Carrinho, perfil selecionado e preferências ficam neste navegador. O usuário Roblox é consultado nas APIs públicas da plataforma. Com pagamento habilitado, e-mail e referência do pedido são enviados à PurinCash para gerar e consultar o PIX. O histórico local não é compartilhado entre dispositivos.':'Esta página representa a navegação da loja. Conteúdos institucionais, suporte, contratos, reembolsos e integrações comerciais da empresa original não foram reproduzidos.'}</p><a class="button" style="margin-top:25px" href="/loja">Voltar à loja →</a></div></section>`}
function currentGame(){return location.pathname.split('/')[2]}
function render(){filter='Todos';query='';let path=location.pathname.replace(/\/$/,'')||'/';if(path==='/loja/roube-um-brainrot'){history.replaceState({},'','/loja/brainrot');path='/loja/brainrot'}const detail=window.productPages?.resolve(path);$('#app').innerHTML=detail?window.productPages.page(detail):path==='/'&&window.landingPage?window.landingPage.page():path==='/loja'||path==='/'?home():games.some(g=>path==='/loja/'+g.id&&g.id!=='custom')?catalog(currentGame()):generic(path);document.title=detail?'Comprar '+detail.name+' — Recriação visual':path==='/'?'Início — StarBuxx':(games.find(g=>g.id===currentGame())?.name||(path==='/perfil/configuracoes'?'Configurações':path==='/perfil/notificacoes'?'Notificações':path==='/perfil/ranking'?'Ranking':path==='/perfil/saldo'?'Meu saldo':(path==='/perfil'||path==='/minha-conta')?'Meu Perfil':path==='/meus-pedidos'?'Meus Pedidos':path==='/robux'?'Robux':path==='/gift-cards'?'Gift Cards':path.startsWith('/contas')?'Contas Blox Fruits':'Loja'))+' — Recriação visual';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===path||(['/contas','/gift-cards','/robux'].includes(a.getAttribute('href'))&&path.startsWith(a.getAttribute('href')+'/'))));save();window.lojaMotion?.mount();window.lojaMedia?.mount();window.landingPage?.mount();window.robuxPage?.mount();window.productPages?.mount();window.accountUI?.mount();window.paymentUI?.mount();}
function addRobuxPacket(spec){const row={id:'robux-'+spec.quantity+'-'+spec.method,kind:'robux',robuxQuantity:spec.quantity,method:spec.method,qty:1};if(!validRobuxRow(row))return;const found=cart.find(item=>item.id===row.id);if(found)found.qty++;else cart.push(row);save();window.lojaMotion?.cart();toast('Pacote de Robux adicionado ao carrinho')}
window.lojaCart={addRobux:addRobuxPacket,addProduct:spec=>{if(!Number.isInteger(spec.id)||!products[spec.id]||products[spec.id].archived||!Number.isInteger(spec.qty)||spec.qty<1||spec.qty>99)return false;const row=cart.find(r=>r.id===spec.id);if((row?.qty||0)+spec.qty>maxCartQuantity(spec.id)){toast('Limite disponível deste item atingido.');return false}if(row)row.qty+=spec.qty;else cart.push({id:spec.id,qty:spec.qty});save();window.lojaMotion?.cart();toast('Produto adicionado ao carrinho');return true},showCart:cartModal,open:openModal,checkout:startCheckout};
document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.matches('a')){const href=target.getAttribute('href');if(href?.startsWith('/')&&!e.ctrlKey&&!e.metaKey){e.preventDefault();history.pushState({},'',href);closeModal(true);$('nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0);return}}if(target.hasAttribute('data-cart'))cartModal();if(target.hasAttribute('data-add'))add(Number(target.dataset.add));if(target.hasAttribute('data-product'))productModal(Number(target.dataset.product));if(target.hasAttribute('data-step')){const [rawId,rawDelta]=target.dataset.step.split(',');const id=/^\d+$/.test(rawId)?Number(rawId):rawId,delta=Number(rawDelta);const row=cart.find(x=>x.id===id);if(!row)return;if(delta>0&&row.qty>=maxCartQuantity(id)){toast('Limite disponível deste item atingido.');return}row.qty+=delta;cart=cart.filter(x=>x.qty>0);save();cartModal()}if(target.hasAttribute('data-remove')){cart=cart.filter(x=>String(x.id)!==target.dataset.remove);save();cartModal()}if(target.matches('.close,[data-close]'))closeModal();if(target.hasAttribute('data-checkout'))startCheckout();if(target.hasAttribute('data-buy-now')){if(add(Number(target.dataset.buyNow)))startCheckout()}if(target.hasAttribute('data-qty')){qty=Number(target.dataset.qty);$('#quantity').value=qty;updatePrice()}if(target.hasAttribute('data-shop-method')){if(target.dataset.shopMethod==='giftcard'){const input=$('#quantity');if(input&&!input.checkValidity()){input.reportValidity();return}window.robuxPage?.createGiftCard(qty);return}shopMethod=target.dataset.shopMethod;target.closest('.calculator').outerHTML=calculator();return}if(target.hasAttribute('data-robux')){if(!$('#quantity').checkValidity()){$('#quantity').reportValidity();return}history.pushState({},'','/robux?qty='+qty+'&method=plus');render();window.scrollTo(0,0)}if(target.hasAttribute('data-top'))window.scrollTo({top:0,behavior:'smooth'});if(target.id==='menu'){const open=$('nav').classList.toggle('open');target.setAttribute('aria-expanded',open)}});
function updatePrice(){const raw=Number($('#quantity').value);qty=Number.isFinite(raw)?raw:0;$('#robux-price').textContent=money(window.shopPricing.robux(qty));$('#economized').textContent=`Economize ${money(qty*.06-window.shopPricing.robux(qty))} · No Roblox: ${money(qty*.06)}`;document.querySelectorAll('[data-qty]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.qty)===qty));window.lojaMotion?.price();}
document.addEventListener('input',e=>{if(e.target.id==='quantity')updatePrice();if(e.target.id==='game-search'){const q=e.target.value.trim().toLowerCase();let count=0;document.querySelectorAll('[data-game-name]').forEach(card=>{let match=card.dataset.gameName.includes(q);card.classList.toggle('hide',!match);count+=match});$('#game-empty').classList.toggle('hide',count>0);window.lojaMotion?.revealResults()}if(e.target.id==='product-search'){query=e.target.value;$('#catalog-list').innerHTML=catalogList(currentGame());window.lojaMotion?.mount()}});
document.addEventListener('change',e=>{if(e.target.id==='category'){filter=e.target.value;$('#catalog-list').innerHTML=catalogList(currentGame());window.lojaMotion?.mount()}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login')toast('Acesso simulado. Nenhum dado foi enviado.');if(e.target.id==='custom')toast('Gamepass simulada. Nenhuma solicitação foi enviada.')});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});window.addEventListener('popstate',render);render();

